import{_ as e,o as a,c as i,aA as n}from"./chunks/framework.BzaFumFl.js";const s="/EegFun.jl/dev/tutorials/signal_example_decoding.png",u=JSON.parse('{"title":"Simulate Decoding — MVPA Playground","description":"","frontmatter":{},"headers":[],"relativePath":"demos/teaching/signal_example_decoding.md","filePath":"demos/teaching/signal_example_decoding.md","lastUpdated":null}'),r={name:"demos/teaching/signal_example_decoding.md"};function l(o,t,d,h,g,c){return a(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="Simulate-Decoding-—-MVPA-Playground" tabindex="-1">Simulate Decoding — MVPA Playground <a class="header-anchor" href="#Simulate-Decoding-—-MVPA-Playground" aria-label="Permalink to &quot;Simulate Decoding — MVPA Playground {#Simulate-Decoding-—-MVPA-Playground}&quot;">​</a></h1><p>Interactive demo showing time-resolved multivariate pattern classification (MVPA/decoding) on synthetic EEG data.</p><img src="'+s+`" alt="Simulate Decoding"><h2 id="What-it-shows" tabindex="-1">What it shows <a class="header-anchor" href="#What-it-shows" aria-label="Permalink to &quot;What it shows {#What-it-shows}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Element</th><th style="text-align:right;">Description</th></tr></thead><tbody><tr><td style="text-align:right;">Blue/Red lines</td><td style="text-align:right;">Mean ERP waveforms for Condition A and B (channel average), with ±1 SE shading</td></tr><tr><td style="text-align:right;">Black line</td><td style="text-align:right;">Time-resolved SVM classification accuracy</td></tr><tr><td style="text-align:right;">Grey dashed line</td><td style="text-align:right;">50% chance level — accuracy here means no decodable information</td></tr></tbody></table><p><strong>The core insight:</strong> at each time point, a Support Vector Machine (SVM) classifier tries to distinguish the two conditions using the pattern of activity across channels. Accuracy above chance means the brain&#39;s response to the two conditions is reliably different at that moment.</p><h2 id="Key-Concepts" tabindex="-1">Key Concepts <a class="header-anchor" href="#Key-Concepts" aria-label="Permalink to &quot;Key Concepts {#Key-Concepts}&quot;">​</a></h2><p><strong>Multivariate vs. univariate:</strong> A t-test compares one channel at a time. MVPA considers the <em>joint pattern</em> across all channels simultaneously — exploiting spatial correlations that univariate methods miss. This is why more channels can improve decoding even when individual channels show weak effects.</p><p><strong>Cross-validation:</strong> The data is split into training and test sets. The SVM learns the pattern from training data and is tested on data it has never seen. This prevents <strong>overfitting</strong> — being fooled by noise patterns that don&#39;t generalise.</p><p><strong>Effect size and SNR:</strong> Signal Strength controls how different the two conditions are. With zero signal, accuracy bounces around 50% (chance). As signal increases, accuracy rises. But noise fights back — high noise can bury even a strong signal if you don&#39;t have enough trials.</p><h2 id="Things-to-Try" tabindex="-1">Things to Try <a class="header-anchor" href="#Things-to-Try" aria-label="Permalink to &quot;Things to Try {#Things-to-Try}&quot;">​</a></h2><ol><li><p><strong>Default settings:</strong> press Decode! — you should see accuracy rising above chance in the effect window.</p></li><li><p><strong>Kill the signal:</strong> set Signal Strength = 0, decode → accuracy fluctuates around 50%. This is the null distribution.</p></li><li><p><strong>Crank the signal:</strong> set Signal Strength = 3 → accuracy approaches 100%.</p></li><li><p><strong>Multivariate advantage:</strong> set N Channels = 1, decode. Then set N Channels = 10, decode again — more channels = higher accuracy.</p></li><li><p><strong>Trial count matters:</strong> set N Trials = 10 → noisy, unreliable curve. Set N Trials = 200 → smooth, stable curve.</p></li><li><p><strong>Timing information:</strong> shift Effect Onset to 0.5 s → accuracy peak shifts to match. Change Duration to see the peak widen or narrow.</p></li></ol><h2 id="Controls" tabindex="-1">Controls <a class="header-anchor" href="#Controls" aria-label="Permalink to &quot;Controls {#Controls}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Control</th><th style="text-align:right;">Range</th><th style="text-align:right;">Description</th></tr></thead><tbody><tr><td style="text-align:right;">Signal Strength</td><td style="text-align:right;">0–3</td><td style="text-align:right;">Amplitude of the condition difference</td></tr><tr><td style="text-align:right;">Noise Level</td><td style="text-align:right;">0.1–5</td><td style="text-align:right;">Background noise amplitude</td></tr><tr><td style="text-align:right;">N Trials</td><td style="text-align:right;">10–200</td><td style="text-align:right;">Trials per condition</td></tr><tr><td style="text-align:right;">N Channels</td><td style="text-align:right;">1–10</td><td style="text-align:right;">Number of EEG channels (SVM features)</td></tr><tr><td style="text-align:right;">Effect Onset</td><td style="text-align:right;">−0.2–0.8 s</td><td style="text-align:right;">When the condition difference begins</td></tr><tr><td style="text-align:right;">Effect Duration</td><td style="text-align:right;">0.05–0.8 s</td><td style="text-align:right;">How long the condition difference lasts</td></tr><tr><td style="text-align:right;">Decode!</td><td style="text-align:right;">button</td><td style="text-align:right;">Runs the SVM classification</td></tr></tbody></table><h2 id="See-Also" tabindex="-1">See Also <a class="header-anchor" href="#See-Also" aria-label="Permalink to &quot;See Also {#See-Also}&quot;">​</a></h2><ul><li><p><a href="./simulate_erp">Simulate ERP</a> — how trial averaging extracts signals from noise</p></li><li><p>Grootswagers, T., Wardle, S. G., &amp; Carlson, T. A. (2017). Decoding dynamic brain patterns from evoked responses: a tutorial on multivariate pattern analysis applied to time series neuroimaging data. <em>Journal of Cognitive Neuroscience</em>, 29(4), 677–697.</p></li></ul><h2 id="Code" tabindex="-1">Code <a class="header-anchor" href="#Code" aria-label="Permalink to &quot;Code {#Code}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> EegFun</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EegFun</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">signal_example_decoding</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div>`,18)])])}const y=e(r,[["render",l]]);export{u as __pageData,y as default};
